interface WorldState {
  entities: Record<string, string>;
}

const initialState = (): WorldState => ({
  entities: { Zef: "pex" },
});

const findEntityKey = (
  entities: Record<string, string>,
  displayName: string
): string | undefined => {
  if (Object.prototype.hasOwnProperty.call(entities, displayName)) {
    return displayName;
  }

  const normalizedName = displayName.toLowerCase();
  return Object.keys(entities).find(
    (key) => key.toLowerCase() === normalizedName
  );
};

export const protocol: WorldProtocol = {
  reset(): WorldState {
    return initialState();
  },

  applyOperation(
    state: WorldState,
    operationDisplayName: string
  ): { success: true; newState: WorldState } | { success: false; error: string } {
    const zefKey = findEntityKey(state.entities, "Zef");
    const zefState = zefKey === undefined ? undefined : state.entities[zefKey];

    if (operationDisplayName === "advanceZef") {
      if (zefState !== "pex") {
        return {
          success: false,
          error: "Zef can only advance from pex",
        };
      }

      return {
        success: true,
        newState: {
          entities: {
            ...state.entities,
            [zefKey ?? "Zef"]: "dor",
          },
        },
      };
    }

    if (operationDisplayName === "recoverZef") {
      if (zefState !== "dor") {
        return {
          success: false,
          error: "Zef can only recover from dor",
        };
      }

      return {
        success: true,
        newState: {
          entities: {
            ...state.entities,
            [zefKey ?? "Zef"]: "pex",
          },
        },
      };
    }

    return {
      success: false,
      error: `Unknown operation: ${operationDisplayName}`,
    };
  },

  getEntityState(state: WorldState, entityDisplayName: string): string {
    const key = findEntityKey(state.entities, entityDisplayName);
    return key === undefined ? "unknown" : state.entities[key];
  },

  toAbstractSnapshot(state: WorldState): Record<string, string> {
    return { ...state.entities };
  },
};
